<script setup>
import { onMounted, ref } from 'vue'
import { api, state, refreshCart, cartSubtotal } from '../lib/store.js'
import { money } from '../lib/catalog.js'
import CartLines from '../components/CartLines.vue'
import Notices from '../components/Notices.vue'
import Icon from '../components/Icon.vue'
const error = ref(''), busy = ref(false)
onMounted(async () => { try { await refreshCart() } catch (e) { error.value = e.message } })
async function change(item, quantity) { busy.value = true; error.value = ''; try { await api(`/cart/${item.itemId}`, quantity === null ? { method: 'DELETE' } : { method: 'PUT', body: { quantity } }); await refreshCart() } catch (e) { error.value = e.message } finally { busy.value = false } }
</script>
<template><section class="page"><div class="page-intro"><span class="eyebrow">DEINE LIEBLINGSSTÜCKE</span><h1>Dein Warenkorb</h1></div><Notices :error="error" /><div v-if="state.cart.length" class="cart-layout"><CartLines :items="state.cart"><template #default="{ item }"><div class="quantity-row"><div class="quantity-control"><button :aria-label="`Menge von ${item.product?.name} verringern`" :disabled="busy || item.quantity <= 1" @click="change(item, item.quantity - 1)"><Icon name="minus" /></button><span aria-live="polite">{{ item.quantity }}</span><button :aria-label="`Menge von ${item.product?.name} erhöhen`" :disabled="busy" @click="change(item, item.quantity + 1)"><Icon name="plus" /></button></div><button class="text-button muted" :disabled="busy" @click="change(item, null)">Löschen</button></div></template></CartLines><aside class="summary-box"><h2>Deine Übersicht</h2><div class="row between summary-total"><span>Zwischensumme</span><strong>{{ money(cartSubtotal()) }}</strong></div><p class="muted">Versandkosten werden im nächsten Schritt berechnet.</p><RouterLink to="/kasse" class="button full-width">Zur Kasse <Icon name="arrow" /></RouterLink><div v-if="!state.user" class="cart-login"><h3>Schon ein Konto?</h3><p>Melde dich an oder erstelle ein Konto, um deinen Warenkorb zu übernehmen.</p><div class="row"><RouterLink :to="{ path: '/login', query: { von: 'warenkorb' } }" class="underlined-link">Anmelden</RouterLink><RouterLink :to="{ path: '/registrieren', query: { von: 'warenkorb' } }" class="underlined-link">Registrieren</RouterLink></div><p class="muted">Du kannst auch als Gast zur Kasse gehen.</p></div></aside></div><div v-else class="empty-state"><Icon name="bag" /><p>Dein Warenkorb ist leer.</p><RouterLink class="button" to="/damen">Kollektion entdecken <Icon name="arrow" /></RouterLink></div></section></template>
